const jobFields=[['JOB_TITLE','Project title','input'],['JOB_OWNER','Project owner','input'],['EXACT_USER_OBJECTIVE_VERBATIM','Verbatim job request','textarea'],['SUPPLIED_MATERIALS_INVENTORY','Supplied materials / files','textarea'],['REQUIRED_OUTPUT_FORMAT','Output format (optional)','input'],['DEADLINE_OR_TEMPORAL_SCOPE','Temporal scope','input'],['DESIRED_SOURCE_COUNT','Desired / suggested source count (optional)','number'],['KNOWN_AUTHORITATIVE_SOURCES','Known authority supplied by user','textarea'],['AVAILABLE_TOOLS','Allowed / required tools','textarea'],['PROHIBITED_ACTIONS','Prohibited actions','textarea'],['EXPLICIT_USER_REQUIREMENTS','Explicit user requirements','textarea']];
function projectViewBase(){const derived=['JOB_ID','DATE_OPENED','CURRENT_ITERATION','CURRENT_STAGE','CURRENT_STATE','CURRENT_INPUT_VERSION','CURRENT_SOURCE_SET_VERSION','CURRENT_REQUIREMENTS_VERSION','CURRENT_TEST_SUITE_VERSION','CURRENT_INSTRUCTION_VERSION','CURRENT_BASELINE_ID','CURRENT_PRODUCT_ID','CURRENT_BLOCKERS','NEXT_REQUIRED_ACTION','LATEST_EVIDENCE_REFERENCE'];return `<div class="panel"><h2 class="section-title">Project information</h2><p class="section-intro">Enter only genuine human-owned User Job Input. The source count is a search target, not a quota. Project-relevant information is supplied once and then reused from canonical project state; do not re-enter data already captured. This static application does not itself access external repositories, websites, or accounts. The application derives workflow identity, versions, status, counts, and next action.</p><div class="grid-2">${jobFields.map(([k,l,t])=>`<div class="field${t==='textarea'?' full':''}"><label>${l}</label>${t==='textarea'?`<textarea data-job="${k}">${esc(current.job[k]||'')}</textarea>`:`<input data-job="${k}" type="${t==='number'?'number':'text'}"${t==='number'?' min="0" step="1" inputmode="numeric" placeholder="Leave blank if unknown"':''} value="${esc(current.job[k]??'')}">`}${k==='REQUIRED_OUTPUT_FORMAT'?'<span class="help">You do not need to know the final file format in advance. A specification substitute requires human confirmation.</span>':t==='number'?'<span class="help">Whole number only. Leave blank if unknown or no preference.</span>':''}</div>`).join('')}</div><div class="button-row"><button class="primary" id="save-job">Save User Job Input</button></div></div><div class="panel"><h2 class="section-title">Application-derived job control</h2>${details('Current derived values',Object.fromEntries(derived.map(k=>[k,current.job[k]])),true)}</div>${Object.keys(current.projectData.userEntered||{}).length?`<div class="panel"><h2 class="section-title">Original project input</h2>${details('User-entered data',current.projectData.userEntered,true)}</div>`:''}`;}
function stagePlanItems(stage=current.activeStage,operation=selectedOperation(stage)){const n=Number(stage),items=engine.testExecutionPlan(current).items;if(n===22)return items.filter(item=>item.testType==='DETERMINISTIC');if(n===23)return items.filter(item=>item.testType==='MEANING');if(n===24)return items.filter(item=>item.testType==='ADVERSARIAL');return items;}
function nativeStage22Tests(){if(Number(current?.activeStage)!==22)return [];const productId=String(current.job?.CURRENT_PRODUCT_ID||''),existing=new Set(engine.records(current,'deterministicResults').filter(r=>engine.isActiveRecord(r)).map(r=>String(engine.recordValue(r,'TEST_ID')||r.relationships?.TEST_ID||'')));return stagePlanItems(22,'COMPLETE').filter(item=>item.executionMode==='APPLICATION_DETERMINISTIC'&&item.executableNow&&!existing.has(item.testId)&&engine.records(current,'tests').some(t=>engine.recordId(t,'tests')===item.testId&&globalThis.closedLoopTestRuntime?.supports(t))&&productId);}
