function nextPromptInstructionId(stage){const existing=safe(current.projectData.generatedPrompts).filter(record=>Number(record.stage)===Number(stage));return `INSTRUCTION-${String(current.job.JOB_ID||'UNKNOWN').replace(/[^A-Za-z0-9-]/g,'')}-S${String(stage).padStart(2,'0')}-${String(existing.length+1).padStart(3,'0')}`;}
