function projectManagementMarkup(){
  const jobId=String(current?.job?.JOB_ID||'').trim();if(!jobId)return '';
  const archived=projects.filter(project=>projectIsArchived(project)),lastEvent=safe(current.projectData.history).at(-1),health=globalThis.closedLoopStorageHealth||{},lastBackup=projectStorage.lastBackup?{at:projectStorage.lastBackup}:null,backupDecision=sensitiveBackupAcknowledgmentMarkup('acknowledge-unencrypted-sensitive-export-management');
  const properties={DISPLAY_NAME:projectDisplayName(current),JOB_ID:jobId,CURRENT_STAGE:current.job.CURRENT_STAGE,CURRENT_STATE:current.job.CURRENT_STATE,PROJECT_REVISION:current.revision,CURRENT_INPUT_VERSION:current.job.CURRENT_INPUT_VERSION,CURRENT_SOURCE_SET_VERSION:current.job.CURRENT_SOURCE_SET_VERSION,CURRENT_REQUIREMENTS_VERSION:current.job.CURRENT_REQUIREMENTS_VERSION,CURRENT_TEST_SUITE_VERSION:current.job.CURRENT_TEST_SUITE_VERSION,CURRENT_INSTRUCTION_VERSION:current.job.CURRENT_INSTRUCTION_VERSION,CURRENT_ITERATION:current.job.CURRENT_ITERATION,CURRENT_CANDIDATE_ID:current.job.CURRENT_CANDIDATE_ID||'NONE',CURRENT_BASELINE_ID:current.job.CURRENT_BASELINE_ID,CURRENT_PRODUCT_ID:current.job.CURRENT_PRODUCT_ID,CURRENT_BLOCKERS:current.job.CURRENT_BLOCKERS,LAST_CANONICAL_EVENT:lastEvent?.deviceTimestamp||lastEvent?.createdAt||'NONE',LAST_COMPLETE_BACKUP:lastBackup?.at||'NONE'};
  const archiveRows=archived.map(project=>`<div class="button-row project-archive-row"><span>${esc(projectDisplayName(project))} · ${esc(project.job.JOB_ID)}</span><button type="button" data-restore-project="${esc(project.job.JOB_ID)}">Restore</button></div>`).join('');
  const danger=`<details class="record-card" id="project-danger-zone"><summary>Danger zone<span>Hidden</span></summary><div class="record-body"><div class="notice danger"><strong>Permanent deletion.</strong><br>This removes this project and every artifact byte stored for it from this browser. Export a complete backup first if you may need it later.</div><div class="field"><label for="delete-project-confirmation">Type the exact JOB_ID to enable deletion</label><input id="delete-project-confirmation" autocomplete="off" autocorrect="off" autocapitalize="none" spellcheck="false" placeholder="${esc(jobId)}" aria-describedby="delete-project-confirmation-help"><span class="help" id="delete-project-confirmation-help">Required: ${esc(jobId)}</span></div><div class="button-row"><button class="danger" id="delete-project" type="button" disabled>Permanently delete project</button></div></div></details>`;
  return `<details class="record-card" id="project-management"><summary>Project management<span>Options</span></summary><div class="record-body"><p class="section-intro">Routine workflow stays separate from project lifecycle actions. Display-name and archive preferences are browser-local management metadata and do not rewrite controlled job identity or accepted evidence.</p><div class="grid-2"><div class="field"><label for="project-display-name">Display name</label><input id="project-display-name" value="${esc(projectDisplayName(current))}"><span class="help">Changes only the human-facing project label. JOB_ID and controlled substantive content remain unchanged.</span></div><div class="field"><label>Safe copy</label><div class="button-row"><button id="duplicate-project" type="button">Start from copy</button></div><span class="help">Copies reusable human-owned job input into a new JOB_ID. Accepted history, evidence, runs, releases, contexts, and stored artifact bytes are not copied as current truth.</span></div></div>${backupDecision}<div class="button-row"><button class="primary" id="rename-project" type="button">Save display name</button><button id="backup-project" type="button">Create backup now</button><button id="archive-project" type="button">Archive project</button></div>${details('Project properties',properties)}<details class="record-card"><summary>Storage & integrity<span>${projectStorage.artifactCount} files</span></summary><div class="record-body"><div class="record-rows">${field('Stored artifact Blob count',projectStorage.artifactCount)}${field('Stored artifact bytes',projectStorage.byteSize)}${field('Last explicit byte verification',projectStorage.lastVerifiedAt||'Not run')}${field('Integrity status',projectStorage.integrity)}${field('Browser storage persistence',health.persistent?'PERSISTENT':'NOT PERSISTENT')}${field('Browser storage usage',health.usage??'UNKNOWN')}${field('Browser storage quota',health.quota??'UNKNOWN')}</div><div class="button-row"><button id="verify-stored-files" type="button">Verify stored files now</button></div>${projectStorage.mismatches.length?`<div class="notice danger">Stored byte mismatch: ${esc(projectStorage.mismatches.join(', '))}</div>`:'<div class="notice">Verification re-reads stored Blob bytes and recomputes SHA-256. It does not mark tests passed or alter release truth.</div>'}</div></details>${archived.length?`<details class="record-card"><summary>Archived projects<span>${archived.length}</span></summary><div class="record-body">${archiveRows}</div></details>`:''}${danger}</div></details>`;
}
function projectView(){return projectViewBase()+projectManagementMarkup();}
function humanStageMarkup(n,locked){if(n===1){if(current.isRetainedTestProject&&current.stages[1].status==='COMPLETE')return `<div class="notice success">Stage 01 is preserved completed history for this retained project. No historical event has been fabricated or rewritten.</div>`;return `<div class="panel"><h2 class="section-title">Human job intake</h2><p class="section-intro">Stage 01 is an intake conversation. Save any facts you already know here, then send the generated instruction and only the files listed for that instruction. Resolve the remaining human-only questions in normal chat using that generated instruction. Continue until those questions are answered or explicitly deferred, then return only the final JSON to this application. HUMAN_INPUT_REQUIRED in this app is only a fallback when a required answer remains unavailable or deferred, or interactive conversation was unavailable.</p><div class="button-row"><button data-view="Project">Open User Job Input</button></div></div>`;}const fields=schema.humanStageFields(n);if(!fields.length)return '';const data=current.stages[n].humanData||{};return `<div class="panel"><h2 class="section-title">Human-owned stage input</h2><div class="grid-2">${fields.map(name=>`<div class="field"><label>${esc(label(name))}</label><input data-human-stage-field="${esc(name)}" value="${esc(data[name]||'')}"${locked?' disabled':''}></div>`).join('')}</div><div class="button-row"><button id="save-human-stage"${locked?' disabled':''}>Save human decision/input</button></div></div>`;}
