async function downloadCanonicalArtifact(artifactId){const id=String(artifactId||''),canonical=engine.records(current,'artifacts').find(record=>engine.recordId(record,'artifacts')===id&&engine.isActiveRecord(record));if(!canonical)throw new Error('The selected canonical artifact is missing or inactive.');if(String(engine.recordValue(canonical,'AVAILABILITY')||'').toUpperCase()!=='BYTES_PERSISTED_AND_VERIFIED')throw new Error('The selected artifact does not have application-verified stored bytes.');const stored=await projectStore.getArtifact(id);if(!stored||String(stored.jobId)!==String(current.job.JOB_ID))throw new Error('The exact stored artifact bytes are unavailable for this project.');const bytes=await stored.blob.arrayBuffer(),actualSha256=await globalThis.closedLoopHash.sha256Bytes(bytes),expectedSha256=String(engine.recordValue(canonical,'SHA256')||''),expectedSize=Number(engine.recordValue(canonical,'BYTE_SIZE')),expectedFilename=String(engine.recordValue(canonical,'FILENAME')||stored.filename||id);if(bytes.byteLength!==expectedSize||actualSha256!==expectedSha256||String(stored.sha256)!==expectedSha256||Number(stored.byteSize)!==expectedSize||String(stored.filename)!==expectedFilename)throw new Error('Stored bytes no longer match the canonical filename, byte size, and SHA-256. Download was blocked.');const url=URL.createObjectURL(stored.blob),a=document.createElement('a');a.href=url;a.download=expectedFilename;a.click();setTimeout(()=>URL.revokeObjectURL(url),0);announce('verified artifact ready for transfer: '+expectedFilename);}
