 const metrics=engine.releaseMetrics(current),stage=canonicalCurrentStage(),action=currentNextAction(),terminal=engine.terminalDeliveryState(current),deliveryRecords=currentCollection('deliveryRecords'),deliveryCandidate=deliveryRecords.filter(record=>record?.active!==false&&!record?.invalidatedBy&&String(recordValue(record,'DELIVERY_STATE')||record.DELIVERY_STATE||'').toUpperCase()==='AUTHORIZED').at(-1)||null,delivery=terminal.authorized?deliveryCandidate:null,deliveryState=terminal.authorized&&delivery?'AUTHORIZED':'',calculateAllowed=stage===27&&action.actionType==='CALCULATE_RELEASE',identityAllowed=stage===28&&action.actionType==='ATTACH_REQUIRED_FILES'&&!action.blockingReason,auditedReady=safe(current.release?.auditedDraft).length>0,deliveryReady=safe(current.release?.releaseDraft).length>0,terminalMessage=deliveryState==='AUTHORIZED'?'Final delivery is authorized by the current application-owned DELIVERY_RECORD.':stage<27?'Release controls are inactive until the structured current action reaches Stage 27. Delivery is not authorized.':stage===27?'Stage 27 calculates product eligibility for final delivery checks. ACCEPTED means PRODUCT_RELEASE_ELIGIBLE only; delivery is not authorized.':stage===28?'Stage 28 verifies one-to-one identity for the selected delivery bytes. Delivery is not yet authorized.':stage===29?'Stage 29 verifies current mandatory evidence-chain closure. Delivery is not yet authorized.':deliveryCandidate?'A DELIVERY_RECORD exists, but final delivery remains unauthorized until every current terminal closure check is complete.':'Stage 30 must verify permanent registry integrity and create a current DELIVERY_RECORD. Delivery is not authorized unless the application confirms every terminal prerequisite remains current.',terminalStatus=deliveryState||(stage===27?String(metrics.determination||'PENDING'):stage===28?'IDENTITY CHECK':stage===29?'EVIDENCE CHECK':'BLOCKED');
